public class LogPurgeJob implements Schedulable, Database.Batchable<sObject> {

    /**
     * No-argument constructor as required.
     */
    public LogPurgeJob() {
    }

    /**
     * Implementation of Schedulable interface.
     * When the scheduled job runs, it executes this batch job.
     */
    public void execute(SchedulableContext sc) {
        Database.executeBatch(new LogPurgeJob());
    }

    /**
     * Implementation of Batchable start method.
     * Defines the scope of records to be processed.
     * 
     * Retention Logic:
     * - If Level__c is 'ERROR', keep until > 180 days old.
     * - Otherwise (if Level__c is not 'ERROR' or is null), keep until > 30 days old.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        DateTime thirtyDaysAgo = DateTime.now().addDays(-30);
        DateTime oneEightyDaysAgo = DateTime.now().addDays(-180);

        // We define the query to select records that meet the deletion criteria.
        // To ensure the most robust SOQL execution, we handle the 'null' case for 
        // Level__c explicitly, as the != operator in SOQL excludes null values.
        return Database.getQueryLocator([
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE (Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo)
               OR (CreatedDate < :thirtyDaysAgo AND (Level__c != 'ERROR' OR Level__c = null))
        ]);
    }

    /**
     * Implementation of Batchable execute method.
     * Deletes the identified scope of records.
     */
    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        if (scope != null && !scope.isEmpty()) {
            delete scope;
        }
    }

    /**
     * Implementation of Batchable finish method.
     */
    public void finish(Database.BatchableContext bc) {
        // No further action required after completion.
    }

    /**
     * Schedules the job to run every day at 02:00 AM.
     * @return The Id of the scheduled job.
     */
    public static Id scheduleNightly() {
        // Cron expression for 02:00 AM every day: 
        // Seconds Minutes Hours DayOfMonth Month DayOfWeek
        String cronExpr = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpr, new LogPurgeJob());
    }
}
