        for (Opportunity opp : (List<Opportunity>) getSObjectList()) {
            if (opp.StageName == 'Closed Won') {
                idsToFulfil.add(opp.Id);
            }
        }

        if (!idsToFulfil.isEmpty()) {
            Application.Service.newInstance(IOpportunityFulfilmentService.class).startFulfilment(idsToFulfil);
        }
    }

    public override void onAfterUpdate() {
        Set<Id> idsToFulfil = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) getSObjectList()) {
            Opportunity oldOpp = (Opportunity) getOldMap().get(opp.Id);
            if (opp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                idsToFulfil.add(opp.Id);
            }
        }

        if (!idsToFulfil.isEmpty()) {
            Application.Service.newInstance(IOpportunityFulfilmentService.class).startFulfilment(idsToFulfil);
        }
