public class Accounts extends fflib_SObjects implements IAccounts {

    public Accounts(List<SObject> records) {
        super(records);
    }

    public static IAccounts newInstance(List<Account> records) {
        return (IAccounts) Application.Domain.newInstance(Account.SObjectType, records);
    }

    public static IAccounts newInstance(Set<Id> accountIds) {
        List<Account> records = (List<Account>) Application.Selector.newInstance(Account.SObjectType).selectById(accountIds);
        return newInstance(records);
    }

    public override Object getSObjectType() {
        return Account.SObjectType;
    }

    public override Object getType() {
        return Account.SObjectType;
    }

    public List<Account> getAccounts() {
        return (List<Account>) this.records;
    }

    public IAccounts selectByRating(String rating) {
        List<Account> matching = new List<Account>();
        for (Account acc : (List<Account>) this.records) {
            if (acc.Rating == rating) {
                matching.add(acc);
            }
        }
        return newInstance(matching);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account acc : (List<Account>) this.records) {
            if (acc.OwnerId != null) {
                ownerIds.add(acc.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (Account acc : (List<Account>) this.records) {
            acc.Rating = rating;
        }
    }

    public class Constructor {
        public Constructor() {}

        public Object construct(List<SObject> records) {
            return new Accounts(records);
        }
    }
}
