/**
 * ErpCustomerSync handles the synchronization of Accounts to the external ERP system.
 * 
 * Implementation Details:
 * - Uses Batch Apex to process accounts in separate transactions.
 * - The scope size is set to 1 to ensure that every account results in a 
 *   unique HTTP request, fulfilling the requirement for ERP traceability.
 * - Implements Database.AllowsCallouts to permit HTTP requests within the batch.
 * - This approach avoids 'Too many callouts: 101' by isolating each callout 
 *   into its own transaction and avoids 'Maximum stack depth' by using 
 *   managed Batch Apex instead of manual Queueable chaining.
 */
public class ErpCustomerSync implements Database.Batchable<sObject>, Database.AllowsCallouts {

    private Set<Id> accountIds;

    /**
     * Constructor to initialize the batch job with specific Account IDs.
     */
    public ErpCustomerSync(Set<Id> accountIds) {
        this.accountIds = accountIds;
    }

    /**
     * Static entry point to initiate the synchronization process.
     * 
     * @param accountIds The set of Account IDs to be synchronized.
     */
    public static void syncAccounts(Set<Id> accountIds) {
        if (accountIds != null && !accountIds.isEmpty()) {
            // We use a scope size of 1. This means each execute() call 
            // handles exactly one Account, resulting in exactly one 
            // HTTP request per account, as requested by Finance.
            Database.executeBatch(new ErpCustomerSync(accountIds), 1);
        }
    }

    /**
     * Returns the scope of records to be processed.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, Name, BillingCountry 
            FROM Account 
            WHERE Id IN :accountIds
        ]);
    }

    /**
     * Executes the callout for each account in the current scope.
     */
    public void execute(Database.BatchableContext bc, List<Account> scope) {
        for (Account acc : scope) {
            // Construct the JSON payload as a single-item array: [{"salesforceId": "...", ...}]
            Map<String, Object> customerMap = new Map<String, Object>{
                'salesforceId' => acc.Id,
                'name' => acc.Name,
                'country' => acc.BillingCountry
            };

            List<Map<String, Object>> payload = new List<Map<String, Object>>{ customerMap };
            String jsonBody = JSON.serialize(payload);

            // Configure the HTTP Request
            HttpRequest request = new HttpRequest();
            request.setEndpoint('callout:ERP/api/customers');
            request.setMethod('POST');
            request.setHeader('Content-Type', 'application/json');
            request.setBody(jsonBody);

            Http http = new Http();
            try {
                // Perform the callout
                http.send(request);
            } catch (Exception e) {
                // Error handling and retries are explicitly out of scope for this ticket.
            }
        }
    }

    /**
     * Cleanup logic after the entire batch has been processed.
     */
    public void finish(Database.BatchableContext bc) {
        // No post-processing required.
    }
}
