import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading = '';
    @api get heading() {
        return this._heading ? this._heading.toUpperCase() : '';
    }
    @api set heading(value) {
        this._heading = value;
    }

    _tasks = [];
    @api get tasks() {
        return this._tasks;
    }
    @api set tasks(value) {
        this._tasks = value;
        // Replace the local items with a deep copy of the tasks array
        this.items = (value || []).map(task => ({ ...task }));

        // Ensure nextId is unique by finding the highest existing ID
        const ids = this.items.map(t => t.id);
        const numericIds = ids.map(id => {
            const match = id.match(/^new-(\d+)$/);
            return match ? parseInt(match[1], 10) : parseInt(id, 10);
        }).filter(n => !isNaN(n));

        this.nextId = numericIds.length > 0 ? Math.max(...numericIds) + 1 : 1;
    }

    items = [];
    newLabel = '';
    nextId = 1;

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const trimmedLabel = this.newLabel ? this.newLabel.trim() : '';
        if (!trimmedLabel) {
            return;
        }

        const newTask = { 
            id: `new-${this.nextId++}`, 
            label: trimmedLabel, 
            done: false 
        };

        // Use spreading to update items array to trigger reactivity
        this.items = [...this.items, newTask];
        this.newLabel = '';

        // Dispatch the taskadded event (lowercase) with the trimmed label
        this.dispatchEvent(new CustomEvent('taskadded', { 
            detail: { label: trimmedLabel } 
        }));
    }

    handleToggle(event) {
        const taskId = event.target.dataset.id;
        const isChecked = event.target.checked;

        // Create a new array and new task object to ensure immutability and reactivity
        this.items = this.items.map(task => {
            if (task.id === taskId) {
                return { ...task, done: isChecked };
            }
            return task;
        });
    }
}
